import{_ as n,C as a,o as i,c as o,a3 as t,E as s}from"./chunks/framework.BP2ycr77.js";const f=JSON.parse('{"title":"Séance 6 — Réviser le rapport","description":"","frontmatter":{"title":"Séance 6 — Réviser le rapport","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/06-reviser-le-rapport.md","filePath":"modules/01-faisabilite/06-reviser-le-rapport.md"}'),u={name:"modules/01-faisabilite/06-reviser-le-rapport.md"};function d(c,e,p,g,m,h){const r=a("OuCaPerdDesPoints"),l=a("ChasseFautes");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="seance-6-—-reviser-le-rapport" tabindex="-1">Séance 6 — Réviser le rapport <a class="header-anchor" href="#seance-6-—-reviser-le-rapport" aria-label="Permalink to &quot;Séance 6 — Réviser le rapport&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Juger un résumé comme le fera Mélanie : qu&#39;est-ce qu&#39;on apprend sur le projet ?</li><li>Relire le rapport avec la <strong>grille d&#39;évaluation</strong> et repérer ce qui fait perdre des points.</li><li>Relire le <strong>français</strong> d&#39;un texte de rapport : les erreurs qui reviennent, et comment les trouver.</li><li>Poser ses dernières questions sur l&#39;évaluation 1.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La séance se fait en deux temps : <strong>le retour sur le Lab 05 et toute la matière d&#39;abord</strong>, en grand groupe, puis <strong>le reste de la soirée pour le Lab 06</strong>, en équipe, dans votre rapport.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour en grand groupe sur le Lab 05 : trois résumés</td></tr><tr><td style="text-align:left;">18 h 45</td><td style="text-align:left;">Ce qui est évalué dans le rapport</td></tr><tr><td style="text-align:left;">18 h 50</td><td style="text-align:left;">Activité 1 — Où vous perdez des points ?</td></tr><tr><td style="text-align:left;">19 h 10</td><td style="text-align:left;">Le français dans le rapport</td></tr><tr><td style="text-align:left;">19 h 20</td><td style="text-align:left;">Activité 2 — La chasse aux fautes</td></tr><tr><td style="text-align:left;">19 h 40</td><td style="text-align:left;">Vos questions sur l&#39;évaluation 1</td></tr><tr><td style="text-align:left;">19 h 55</td><td style="text-align:left;">Les consignes du Lab 06 et ce qu&#39;il y a à faire à la maison</td></tr><tr><td style="text-align:left;">20 h 00</td><td style="text-align:left;">Marge pour les questions</td></tr><tr><td style="text-align:left;">20 h 10</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 25</td><td style="text-align:left;"><a href="./../../labs/lab06-reviser-le-rapport">Lab 06 — Réviser le rapport</a>, en équipe, jusqu&#39;à la fin de la soirée</td></tr></tbody></table><p>Le <strong>retour en grand groupe</strong> sur le Lab 06 aura lieu <strong>au début de la séance 7</strong>, après la remise.</p><hr><h2 id="retour-lab-05" tabindex="-1">Retour sur le Lab 05 : trois résumés <a class="header-anchor" href="#retour-lab-05" aria-label="Permalink to &quot;Retour sur le Lab 05 : trois résumés {#retour-lab-05}&quot;">​</a></h2><p>Nous réviserons ensemble trois résumés déposés au Lab 05, <strong>sans nommer les équipes</strong>. Vous les entendrez une seule fois, comme Mélanie qui lit vite.</p><p>Après chaque résumé, écrivez dans le chat <strong>une chose que vous avez apprise sur le projet</strong>. Si vous ne trouvez rien à écrire, ce n&#39;est pas votre faute : c&#39;est que le résumé ne résume pas.</p><p>Comparez ensuite avec le <a href="./05-ecrire-pour-le-client#activite-2">résumé proposé à l&#39;activité 2 de la séance 5</a> : ce qu&#39;il dit d&#39;abord, ce qu&#39;il garde pour la fin, et ce qu&#39;il laisse dans le rapport.</p><hr><h2 id="ce-qui-est-evalue-dans-le-rapport" tabindex="-1">Ce qui est évalué dans le rapport <a class="header-anchor" href="#ce-qui-est-evalue-dans-le-rapport" aria-label="Permalink to &quot;Ce qui est évalué dans le rapport&quot;">​</a></h2><p>Le rapport est corrigé avec la <a href="./../../evaluations/evaluation-1#la-grille-d-evaluation">grille de l&#39;évaluation 1</a>, <strong>critère par critère</strong>. Deux choses à savoir avant de relire le vôtre :</p><ul><li><strong>Le critère 6 vaut le quart de la note.</strong> Votre question en profondeur, les quatre autres en survol, les coûts sur trois ans, les avantages et les limites pour ce client, et aucune recommandation. C&#39;est là qu&#39;une heure de révision rapporte le plus.</li><li><strong>Les mêmes défauts coûtent des points à plusieurs endroits.</strong> Une recommandation glissée dans une mesure de risque, par exemple, se paie au critère 5 et au critère 6.</li></ul><p>La liste <a href="./../../evaluations/evaluation-1#la-grille-d-evaluation">« Ce qui fait perdre des points rapidement »</a>, sous la grille, est votre meilleur outil de relecture. L&#39;activité 1 la met en pratique.</p><h3 id="activite-1" tabindex="-1">Activité 1 — Où vous perdez des points ? <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — Où vous perdez des points ? {#activite-1}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min, en équipe, puis retour en grand groupe)</strong><br> Huit extraits tirés du rapport d&#39;une équipe fictive. Les outils sont inventés. <ol class="list-decimal pl-5"><li>Pour chaque extrait, choisissez le <strong>critère de la grille</strong> qui perdrait des points.</li><li>Écrivez une correction <strong>avant</strong> de regarder celle qui est proposée. Gardez les faits; inventez la mesure ou la source au besoin.</li></ol></div>',19)),s(r),e[1]||(e[1]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> presque tous ces défauts se corrigent de la même façon : remplacer un mot vague par <strong>un chiffre, une source ou un effet sur l&#39;entreprise</strong>. Si une phrase pourrait se copier telle quelle dans le rapport d&#39;un autre client, elle est trop générale.</p><hr><h2 id="le-francais-dans-le-rapport" tabindex="-1">Le français dans le rapport <a class="header-anchor" href="#le-francais-dans-le-rapport" aria-label="Permalink to &quot;Le français dans le rapport&quot;">​</a></h2><p>Le critère 8 vaut <strong>10 points</strong>. L&#39;enseignant choisit dans votre rapport un <strong>extrait d&#39;environ 150 mots</strong> (une quinzaine de lignes) de <strong>texte suivi</strong> : un paragraphe rédigé par l&#39;équipe, pas un tableau ni une liste. Il le corrige selon la Politique du français de la DFCSE. Vous ne savez pas à l&#39;avance quel passage sera choisi : <strong>chaque paragraphe compte</strong>.</p><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>La clarté et le français ne se notent pas au même endroit</strong><br> Le jargon et les phrases trop longues se notent au <strong>critère 1</strong> (organisation et clarté). L&#39;orthographe, la grammaire, la ponctuation et la syntaxe se notent au <strong>critère 8</strong>. Un texte peut être clair et plein de fautes, ou sans faute et incompréhensible pour Mélanie. </div><h3 id="les-erreurs-qui-reviennent-dans-un-rapport-technique" tabindex="-1">Les erreurs qui reviennent dans un rapport technique <a class="header-anchor" href="#les-erreurs-qui-reviennent-dans-un-rapport-technique" aria-label="Permalink to &quot;Les erreurs qui reviennent dans un rapport technique&quot;">​</a></h3><div class="col-non-2 col-oui-3"><table tabindex="0"><thead><tr><th style="text-align:left;">La sorte</th><th style="text-align:left;">Ce qu&#39;on écrit souvent</th><th style="text-align:left;">Ce qu&#39;on écrit plutôt</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Nombres et symboles</strong></td><td style="text-align:left;">2600$ · 55% · 2,5sec · 18h30</td><td style="text-align:left;">2 600 $ · 55 % · 2,5 s · 18 h 30</td></tr><tr><td style="text-align:left;"><strong>Dates</strong></td><td style="text-align:left;">le 1 mars · le 11 Novembre</td><td style="text-align:left;">le 1<sup>er</sup> mars · le 11 novembre</td></tr><tr><td style="text-align:left;"><strong>Accord du participe passé</strong></td><td style="text-align:left;">les outils qu&#39;on a essayé</td><td style="text-align:left;">les outils que nous avons essayés</td></tr><tr><td style="text-align:left;"><strong>Tout, leur</strong></td><td style="text-align:left;">tout les frais · leur tutoriels</td><td style="text-align:left;">tous les frais · leurs tutoriels</td></tr><tr><td style="text-align:left;"><strong>Homophones</strong></td><td style="text-align:left;">reste a vérifier · ses deux outils sont</td><td style="text-align:left;">reste à vérifier · ces deux outils sont</td></tr><tr><td style="text-align:left;"><strong>Anglicismes</strong></td><td style="text-align:left;">supporter Viator · canceller · à date</td><td style="text-align:left;">prendre en charge Viator · annuler · jusqu&#39;à maintenant</td></tr><tr><td style="text-align:left;"><strong>Registre</strong></td><td style="text-align:left;">on a testé ça</td><td style="text-align:left;">nous avons essayé cela</td></tr><tr><td style="text-align:left;"><strong>Ponctuation</strong></td><td style="text-align:left;">Les essais de l&#39;équipe, ont montré…</td><td style="text-align:left;">Les essais de l&#39;équipe ont montré…</td></tr></tbody></table></div><h3 id="une-methode-de-relecture-en-trois-passes" tabindex="-1">Une méthode de relecture en trois passes <a class="header-anchor" href="#une-methode-de-relecture-en-trois-passes" aria-label="Permalink to &quot;Une méthode de relecture en trois passes&quot;">​</a></h3><ol><li><strong>Le correcteur</strong> (Antidote ou celui de Word) : il trouve vite les accords et les fautes d&#39;orthographe. Il ne voit pas tout : un homophone bien orthographié (« a » pour « à ») ou un anglicisme passe souvent.</li><li><strong>La lecture à voix haute</strong>, lentement : les phrases trop longues et les virgules mal placées s&#39;entendent.</li><li><strong>Une autre personne</strong> que celle qui a écrit : on ne voit pas ses propres fautes, parce qu&#39;on lit ce qu&#39;on voulait écrire.</li></ol><p>En cas de doute sur une règle, la <a href="https://vitrinelinguistique.oqlf.gouv.qc.ca/banque-de-depannage-linguistique" target="_blank" rel="noreferrer">Banque de dépannage linguistique de l&#39;Office québécois de la langue française</a> donne la réponse, avec des exemples.</p><h3 id="activite-2" tabindex="-1">Activité 2 — La chasse aux fautes <a class="header-anchor" href="#activite-2" aria-label="Permalink to &quot;Activité 2 — La chasse aux fautes {#activite-2}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min, en équipe, puis retour en grand groupe)</strong><br> Trois passages du brouillon d&#39;une équipe fictive, environ 150 mots en tout : la taille de l&#39;extrait corrigé au critère 8. Les outils sont inventés. <ol class="list-decimal pl-5"><li>Cliquez sur chaque mot ou groupe de mots qui contient une faute, puis sur « Vérifier ».</li><li>Pour chaque faute, dites <strong>quelle règle</strong> elle enfreint avant de lire la réponse.</li></ol></div>',12)),s(l),e[2]||(e[2]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> près du tiers de ces fautes touchent les <strong>nombres, les symboles et les dates</strong>, qu&#39;un correcteur ne signale pas toujours. Ce sont aussi les plus faciles à éliminer : une recherche dans le document (<code>$</code>, <code>%</code>, <code>min</code>, <code>1 </code>) suffit à les trouver.</p><hr><h2 id="questions" tabindex="-1">Vos questions sur l&#39;évaluation 1 <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Vos questions sur l&#39;évaluation 1 {#questions}&quot;">​</a></h2><p>Écrivez vos questions dans le chat au fil de la soirée; on y répond en grand groupe. Voici celles qui reviennent le plus souvent.</p><details class="details custom-block"><summary>Les annexes comptent-elles dans les 15 pages ?</summary><p>Non. Les 10 à 15 pages ne comptent ni la page de titre, ni la table des matières, ni les annexes. Ce qui est en annexe doit tout de même être <strong>résumé</strong> dans le rapport, avec un renvoi : Mélanie ne va pas lire l&#39;annexe A.</p></details><details class="details custom-block"><summary>Peut-on utiliser les résultats des autres équipes ?</summary><p>Oui, pour le survol des quatre autres questions, en indiquant d&#39;où vient l&#39;information : « essai de l&#39;équipe 3, séance 5 ». Ce ne sont pas vos essais : vous ne pouvez pas les mettre dans l&#39;annexe A, et une source documentaire de votre propre recherche doit les compléter.</p></details><details class="details custom-block"><summary>L&#39;outil n&#39;affiche pas son prix. Qu&#39;est-ce qu&#39;on écrit ?</summary><p>« Prix non publié (page consultée le 20 octobre 2026) » est un constat : écrivez-le dans le tableau, et ajoutez-le aux points à vérifier de la section 7. N&#39;inventez pas de montant, et ne communiquez pas avec le vendeur.</p></details><details class="details custom-block"><summary>Peut-on ajouter un glossaire ?</summary><p>Oui, en plus, mais il ne remplace pas l&#39;explication : chaque terme technique est expliqué <strong>la première fois qu&#39;il apparaît dans le texte</strong>, ou évité.</p></details><details class="details custom-block"><summary>« Devrait » est-il interdit ?</summary><p>Dans une exigence, écrivez plutôt « doit » : « La page d&#39;accueil doit s&#39;afficher en moins de 2,5 secondes. » Ailleurs, « devrait » et « il faudrait » annoncent presque toujours une recommandation : gardez le fait, retirez le choix.</p></details><details class="details custom-block"><summary>Quel taux de change utiliser ?</summary><p>Celui du jour où vous avez lu les prix, avec sa date et sa source, écrit sous le tableau avec les autres hypothèses du coût sur trois ans. Le même taux pour tous les outils.</p></details><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab06-reviser-le-rapport">Lab 06 — Réviser le rapport</a>, en équipe, jusqu&#39;à la fin de la soirée. La fiche est votre liste de révision; le travail se fait dans le rapport.</p><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Remise : mercredi 11 novembre, 18 h 30, sur LÉA</strong><br> Un seul fichier <code>.docx</code>, nommé <code>eval1-equipeN-nom1-nom2-nom3.docx</code>, avec les annexes A, B et C. Retard : 10 % par jour. </div><ul><li><strong>Régler les points de révision</strong> notés dans la fiche du Lab 06 (partie 2), en commençant par la section 6.</li><li><strong>Passer chaque section au correcteur</strong>, puis la faire relire par une autre personne de l&#39;équipe.</li><li><strong>Reprendre le résumé</strong> une dernière fois, quand tout le reste est terminé.</li><li><strong>Remplir les annexes B et C</strong>, et faire signer l&#39;annexe C par tous les membres.</li><li><strong>Mettre à jour la table des matières</strong> (clic droit, « Mettre à jour les champs ») et passer la <a href="./../../evaluations/evaluation-1#la-liste-de-verification-avant-la-remise">liste de vérification avant la remise</a>.</li></ul><hr><h2 id="avant-la-seance-7-11-novembre" tabindex="-1">Avant la séance 7 (11 novembre) <a class="header-anchor" href="#avant-la-seance-7-11-novembre" aria-label="Permalink to &quot;Avant la séance 7 (11 novembre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Copier vos réponses des activités 1 et 2 dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 06 dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Régler les points de révision de la fiche, et relire chaque section une dernière fois</span></label></li><li><label><input type="checkbox"><span class="check-text">Chercher dans le rapport final les mots qui recommandent : <code>recommander</code>, <code>recommandation</code>, <code>il faudrait</code>, <code>devrait</code>, <code>meilleur</code>, <code>idéal</code>, <code>privilégier</code></span></label></li><li><label><input type="checkbox"><span class="check-text">Remettre le rapport sur LÉA avant 18 h 30 le 11 novembre</span></label></li></ul>',20))])}const b=n(u,[["render",d]]);export{f as __pageData,b as default};
